  onBarLeave(){ if(!this.state.barHover)return; this.state.barHover=false; var bar=this.q('acp-if[data-k="'+this.state.activeTab+'Bar"] > div'); if(bar){ bar.style.animationPlayState='running'; bar.style.opacity='1'; } if(!this.state.paused) this.scheduleAuto(this._autoRemaining); }

  track(event, props){ try { var mp = (typeof window!=='undefined') && (window.mixpanel || (window.parent && window.parent.mixpanel) || (window.top && window.top.mixpanel)); if(mp && typeof mp.track==='function') mp.track(event, props); } catch(e){} }

