    chain = chain.then(function(){ if(guard())return; self.show('showBubble',true); self.show('typingUser',true); return self.sleep(120); })
      .then(function(){ if(guard())return; return self.typeInto('userText', n.user, seq); })
      .then(function(){ if(guard())return; self.show('typingUser',false); return self.sleep(160); })
