    var wrap=document.createElement('div'); wrap.style.cssText='width:100%;overflow:hidden;'; inner.parentNode.insertBefore(wrap,inner); wrap.appendChild(inner); inner.style.transformOrigin='top left';
    var apply=function(){ var natW=inner.offsetWidth,natH=inner.offsetHeight; if(!natW)return; var s=Math.min(1, wrap.clientWidth/natW); inner.style.transform = s<1?'scale('+s+')':'none'; wrap.style.height=Math.ceil(natH*s)+'px'; };
